//! C#: `Azul.cs` (namespace `Azul`, generated by `doc/src/codegen/v2/lang_csharp`).
//!
//! Spellings (from `target/codegen/Azul.cs`): the raw C functions are
//! `NativeMethods.Az<Class>_<lowerCamel>(..)` (api.json constructors and the
//! enum variant constructors alike); C-like enums are C# enums WITHOUT the
//! `Az` prefix (`LayoutDisplay.Flex`, `CssPropertyType.Width`); structs and
//! tagged unions keep it and have public snake_case fields, so a struct is
//! an object initialiser (`new AzColorU { r = 255, .. }`) and a union member
//! of an explicit-layout union is too (`new AzLayoutWidthValue { Exact = new
//! AzLayoutWidthValueVariant_Exact { tag = AzLayoutWidthValue_Tag.Exact,
//! payload = .. } }`). A Vec needs its items marshalled into native memory:
//! the generated `AzulCodegen.Vec` helper does that and calls
//! `NativeMethods.AzXxxVec_copyFromPtr(ptr, len)`; `AzulCodegen.Str` builds
//! an `AzString` from UTF-8 bytes like the generated wrappers do.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use crate::codegen::{
    doc::{render, Doc},
    ir::{snake_to_lower_camel, EnumShape, Item, Module, Prim},
    lang::{
        escape_quoted, item_comments, item_doc, unicode_u4, variant_ctor_method, ExprSyntax,
    },
    lower_types::is_c_like_enum,
    CodegenBackend, GeneratedFile,
};

/// The C# printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct CSharp;

const KEYWORDS: &[&str] = &[
    "abstract", "as", "base", "bool", "break", "byte", "case", "catch", "char", "checked",
    "class", "const", "continue", "decimal", "default", "delegate", "do", "double", "else",
    "enum", "event", "explicit", "extern", "false", "finally", "fixed", "float", "for",
    "foreach", "goto", "if", "implicit", "in", "int", "interface", "internal", "is", "lock",
    "long", "namespace", "new", "null", "object", "operator", "out", "override", "params",
    "private", "protected", "public", "readonly", "ref", "return", "sbyte", "sealed", "short",
    "sizeof", "stackalloc", "static", "string", "struct", "switch", "this", "throw", "true",
    "try", "typeof", "uint", "ulong", "unchecked", "unsafe", "ushort", "using", "virtual",
    "void", "volatile", "while",
];

fn field(name: &str) -> String {
    if KEYWORDS.contains(&name) {
        format!("@{name}")
    } else {
        name.to_string()
    }
}

/// The C# type name of an api.json type: C-like enums drop the `Az` prefix.
fn ty_name(ty: &str) -> String {
    if is_c_like_enum(ty) {
        ty.to_string()
    } else {
        format!("Az{ty}")
    }
}

impl ExprSyntax for CSharp {
    fn int(&self, value: i128, ty: Prim) -> String {
        match ty {
            Prim::Isize => format!("(nint){value}"),
            Prim::Usize => format!("(nuint){value}"),
            Prim::U64 => format!("{value}UL"),
            Prim::I64 => format!("{value}L"),
            _ => value.to_string(),
        }
    }

    fn float(&self, text: &str, ty: Prim) -> String {
        let (t, suffix) = if ty == Prim::F64 { ("double", "") } else { ("float", "f") };
        match text {
            "nan" => format!("{t}.NaN"),
            "inf" => format!("{t}.PositiveInfinity"),
            "-inf" => format!("{t}.NegativeInfinity"),
            _ => format!("{text}{suffix}"),
        }
    }

    fn boolean(&self, b: bool) -> String {
        b.to_string()
    }

    fn string(&self, s: &str) -> Doc {
        Doc::text(format!(
            "AzulCodegen.Str(\"{}\")",
            escape_quoted(s, &[], &unicode_u4)
        ))
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, broken: bool) -> Doc {
        Doc::call(
            format!("NativeMethods.Az{class}_{}", snake_to_lower_camel(method)),
            args,
            broken,
        )
    }

    fn variant(&self, ty: &str, shape: EnumShape, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
        match shape {
            EnumShape::CLike => Doc::text(format!("{ty}.{variant}")),
            EnumShape::Tagged => Doc::call(
                format!("NativeMethods.Az{ty}_{}", variant_ctor_method(variant)),
                args,
                broken,
            ),
            EnumShape::TaggedShadowed | EnumShape::Generic { .. } => {
                let mut inner = vec![Doc::text(format!("tag = Az{ty}_Tag.{variant}"))];
                if let Some(payload) = args.into_iter().next() {
                    inner.push(Doc::cat(vec![Doc::text("payload = "), payload]));
                }
                Doc::cat(vec![
                    Doc::text(format!("new Az{ty} ")),
                    Doc::list(
                        "{",
                        vec![Doc::cat(vec![
                            Doc::text(format!("{variant} = new Az{ty}Variant_{variant} ")),
                            Doc::list("{", inner, ", ", "}", true, broken, false),
                        ])],
                        ", ",
                        "}",
                        true,
                        broken,
                        false,
                    ),
                ])
            }
        }
    }

    fn strukt(&self, ty: &str, fields: Vec<(String, Doc)>, broken: bool) -> Doc {
        let fields = fields
            .into_iter()
            .map(|(k, v)| Doc::cat(vec![Doc::text(format!("{} = ", field(&k))), v]))
            .collect();
        Doc::cat(vec![
            Doc::text(format!("new Az{ty} ")),
            Doc::list("{", fields, ", ", "}", true, broken, true),
        ])
    }

    fn vec(&self, ty: &str, elem: &str, items: Vec<Doc>, broken: bool) -> Doc {
        if items.is_empty() {
            return Doc::text(format!("NativeMethods.Az{ty}_create()"));
        }
        let mut args = vec![Doc::text(format!("NativeMethods.Az{ty}_copyFromPtr"))];
        args.extend(items);
        Doc::call(
            format!("AzulCodegen.Vec<{}, Az{ty}>", ty_name(elem)),
            args,
            broken,
        )
    }

    fn unsupported(&self, _what: &str) -> Doc {
        Doc::text("default")
    }
}

/// The marshalling helpers every generated file carries.
const HELPERS: &str = r"    internal static class AzulCodegen
    {
        // Copies the items into native memory and lets the C API build the Vec
        // (AzXxxVec_copyFromPtr clones them).
        internal static TVec Vec<T, TVec>(Func<IntPtr, UIntPtr, TVec> copy, params T[] items) where T : struct
        {
            if (typeof(T).IsEnum)
            {
                var raw = new uint[items.Length];
                for (int i = 0; i < items.Length; i++) raw[i] = Convert.ToUInt32(items[i]);
                var handle = GCHandle.Alloc(raw, GCHandleType.Pinned);
                try { return copy(handle.AddrOfPinnedObject(), (UIntPtr)items.Length); }
                finally { handle.Free(); }
            }
            int size = Marshal.SizeOf<T>();
            IntPtr buf = Marshal.AllocHGlobal(Math.Max(1, size * items.Length));
            try
            {
                for (int i = 0; i < items.Length; i++) Marshal.StructureToPtr(items[i], buf + i * size, false);
                return copy(buf, (UIntPtr)items.Length);
            }
            finally { Marshal.FreeHGlobal(buf); }
        }

        internal static AzString Str(string s)
        {
            byte[] bytes = Encoding.UTF8.GetBytes(s);
            IntPtr buf = Marshal.AllocHGlobal(Math.Max(1, bytes.Length));
            try
            {
                Marshal.Copy(bytes, 0, buf, bytes.Length);
                return NativeMethods.AzString_fromUtf8(buf, (UIntPtr)bytes.Length);
            }
            finally { Marshal.FreeHGlobal(buf); }
        }
    }
";

fn item_method(item: &Item) -> String {
    let mut out = String::new();
    for line in &item_comments(&CSharp, item) {
        out.push_str(&format!("        // {line}\n"));
    }
    let name = item.name.upper_camel();
    let ty = ty_name(&item.ty);
    match item_doc(&CSharp, item) {
        Ok(doc) => out.push_str(&format!(
            "        public static {ty} {name}()\n        {{\n            return {};\n        }}\n",
            render(&doc, "    ", 3)
        )),
        Err(reason) => out.push_str(&format!(
            "        // not expressible with the C# bindings: {reason}\n        public static {ty} \
             {name}() => default;\n"
        )),
    }
    out
}

impl CodegenBackend for CSharp {
    fn lang(&self) -> &'static str {
        "csharp"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["c#", "cs", "dotnet"]
    }

    fn display_name(&self) -> &'static str {
        "C#"
    }

    fn extension(&self) -> &'static str {
        "cs"
    }

    fn emit_module(&self, m: &Module) -> String {
        let mut out = String::from(
            "// Generated by azul-css codegen (C#). Do not edit by hand.\nusing System;\nusing \
             System.Runtime.InteropServices;\nusing System.Text;\nusing Azul;\n\nnamespace \
             AzulStyles\n{\n    public static class Styles\n    {\n",
        );
        for (i, item) in m.items.iter().enumerate() {
            if i > 0 {
                out.push('\n');
            }
            out.push_str(&item_method(item));
        }
        out.push_str("    }\n\n");
        out.push_str(HELPERS);
        out.push_str("}\n");
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let mut main = String::from(
            "// Copy Azul.cs (target/codegen) and the azul library next to this file.\nusing \
             System;\n\nclass Program\n{\n    static void Main()\n    {\n",
        );
        for item in &m.items {
            let name = item.name.upper_camel();
            if item.ty.ends_with("Vec") {
                main.push_str(&format!(
                    "        var {0} = AzulStyles.Styles.{1}();\n        Console.WriteLine(\"{1}: \" + \
                     {0}.len + \" properties\");\n",
                    item.name.lower_camel(),
                    name
                ));
            } else {
                main.push_str(&format!(
                    "        AzulStyles.Styles.{name}();\n        Console.WriteLine(\"{name}: \
                     built\");\n"
                ));
            }
        }
        main.push_str("    }\n}\n");
        vec![
            GeneratedFile {
                path: "AzulStyles.csproj".to_string(),
                contents: "<Project Sdk=\"Microsoft.NET.Sdk\">\n  <PropertyGroup>\n    \
                           <OutputType>Exe</OutputType>\n    \
                           <TargetFramework>net8.0</TargetFramework>\n    \
                           <RollForward>Major</RollForward>\n    \
                           <Nullable>enable</Nullable>\n    \
                           <AllowUnsafeBlocks>true</AllowUnsafeBlocks>\n  </PropertyGroup>\n\
                           </Project>\n"
                    .to_string(),
            },
            GeneratedFile {
                path: "Styles.cs".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "Program.cs".to_string(),
                contents: main,
            },
        ]
    }
}
